            new Chart(document.getElementById('bmi-trend'), { type: 'line', data: { labels: trends.bmi.labels, datasets: [{ label: 'BMI', data: trends.bmi.values, borderColor: '#059669', backgroundColor: '#a7f3d0', tension: .35 }, { label: '{{ __('insights.weight') }}', data: trends.weight.values, borderColor: '#0284c7', backgroundColor: '#bae6fd', tension: .35, yAxisID: 'y1' }] }, options: { ...common, scales: { y1: { position: 'right', grid: { drawOnChartArea: false } } } } });
            new Chart(document.getElementById('nutrition-trend'), { type: 'line', data: { labels: trends.nutrition.labels, datasets: [{ label: '{{ __('insights.average_calories') }}', data: trends.nutrition.calories, borderColor: '#f59e0b', backgroundColor: '#fde68a', tension: .3 }, { label: '{{ __('insights.protein') }}', data: trends.nutrition.protein, borderColor: '#7c3aed', tension: .3 }] }, options: common });
            new Chart(document.getElementById('journal-trend'), { data: { labels: trends.journal.labels, datasets: [{ type: 'bar', label: '{{ __('insights.journal_count') }}', data: trends.journal.frequency, backgroundColor: '#38bdf8', borderRadius: 6 }, { type: 'line', label: '{{ __('insights.mood_trend') }}', data: trends.journal.mood_scores, borderColor: '#7c3aed', tension: .3, spanGaps: true, yAxisID: 'y1' }] }, options: { ...common, scales: { y1: { position: 'right', min: 1, max: 5, ticks: { stepSize: 1 }, grid: { drawOnChartArea: false } } } } });
